L108: // Server text reaches an error message only when it is short and fits OAuth's
L109: // error grammar: printable ASCII without `"` or `\` (RFC 6749 appendix A.7, A.8).
L110: const quotable = (value, max = 64) => typeof value === "string" && value.length <= max && /^[\x20-\x21\x23-\x5B\x5D-\x7E]+$/.test(value);
L111: const discoveryTimeoutMs = 10_000;
L112: // OpenID Connect Discovery appends the well-known path to the issuer; RFC 8414
L113: // inserts it between the host and the issuer's path.
L114: function metadataLocations(issuer) {
L115:     const url = new URL(issuer);
L116:     const path = url.pathname.replace(/\/$/, "");
L117:     return [`${url.origin}${path}/.well-known/openid-configuration`, `${url.origin}/.well-known/oauth-authorization-server${path}`];
L118: }
L119: function discover(issuer) {
L120:     return Effect.gen(function* () {
L121:         const found = yield* Effect.tryPromise({
L122:             try: async (signal) => {
L123:                 const deadline = AbortSignal.any([signal, AbortSignal.timeout(discoveryTimeoutMs)]);
L124:                 for (const location of metadataLocations(issuer)) {
L125:                     const response = await fetch(location, {
L126:                         headers: { Accept: "application/json" },
L127:                         redirect: "error",
L128:                         signal: deadline,
L129:                     });
L130:                     if (response.status === 404)
L131:                         continue;
L132:                     if (!response.ok)
L133:                         throw new Error(`authorization server metadata at ${location} answered ${response.status}`);
L134:                     return { location, body: (await response.json().catch(() => undefined)) };
L135:                 }
L136:                 throw new Error(`no authorization server metadata for ${issuer}`);
L137:             },
L138:             catch: (cause) => toError(cause, `authorization server metadata for ${issuer} did not answer within ${discoveryTimeoutMs / 1000} s`),
L139:         });
L140:         const metadata = yield* Schema.decodeUnknownEffect(Metadata)(found.body).pipe(Effect.mapError((error) => {
L141:             const field = failedField(error.issue, Object.keys(Metadata.fields));
L142:             return new Error(field === undefined
L143:                 ? `${found.location} returned no authorization server metadata`
L144:                 : `authorization server metadata has no valid ${field}`);
L145:         }));
L146:         // RFC 8414 section 3.3, OpenID Connect Discovery section 4.3.
L147:         if (metadata.issuer !== issuer) {
L148:             const named = quotable(metadata.issuer, 256) ? `"${metadata.issuer}"` : "a different issuer";
L149:             return yield* Effect.fail(new Error(`authorization server metadata names ${named}, not "${issuer}"`));
L150:         }

{
  "name": "opencode-oauth",
  "version": "0.5.0",
  "description": "OpenCode plugin: sign in to an OpenAI-compatible provider with OAuth 2.0 and PKCE, add its models, and search the web through SearXNG behind the same sign-in",
  "keywords": [
